// Writes db/schema.sql: the migrated schema as one readable file (npm run progress:schema).
// It is generated from the migrations, so it cannot drift; kit/tests/progress/schema.test.mjs checks that.
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { openDb, migrate } from './db.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
export const SCHEMA_FILE = path.join(here, '../../db/schema.sql');

const HEADER = `-- db/schema.sql: the progress database after every migration, in creation order.
-- Generated by \`npm run progress:schema\` (scripts/progress-db/dump-schema.mjs). Do not edit it by hand.
-- The commentary is in db/migrations/*.sql, which is the source of truth; comments inside each
-- CREATE statement are kept here as SQLite stores them.

`;

/** @returns {string} the schema as SQL text, one statement per block, in creation order. */
export function dumpSchema(db) {
  const rows = db.prepare('SELECT sql FROM sqlite_master WHERE sql IS NOT NULL ORDER BY rowid').all();
  return HEADER + rows.map((r) => `${r.sql.trim()};\n`).join('\n');
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const db = openDb(':memory:');
  migrate(db);
  writeFileSync(SCHEMA_FILE, dumpSchema(db));
  console.log(`wrote ${path.relative(process.cwd(), SCHEMA_FILE)}`);
}
